      AR: { agency: 'Arkansas Department of Health, Environmental Health Protection', agencyUrl: 'https://healthy.arkansas.gov/programs-services/topics/food-protection/', fee: '$36–$85 exam', note: 'Adopted the 2013 FDA Food Code. One accredited CFPM required per food establishment.', compactMember: false },
