      AK: { agency: 'Alaska Department of Environmental Conservation, Pesticide Program', agencyUrl: 'https://dec.alaska.gov/eh/pest/', fee: '$50–$150', note: 'One of the states that places pesticide certification in the environmental agency rather than agriculture. Private and commercial classes; the small number of Alaskan applicators means exams are scheduled by arrangement.', compactMember: false },
