      AR: { agency: 'Arkansas Department of Agriculture, Plant Industries Division', agencyUrl: 'https://agriculture.arkansas.gov/plant-industries/', fee: '$20–$150', note: 'Formerly the Arkansas State Plant Board, now a division of the Department of Agriculture. Private, commercial and non-commercial classes; dicamba and auxin herbicide use carries additional state-specific training requirements.', compactMember: false },
      CA: { agency: 'California Department of Pesticide Regulation (DPR), with the County Agricultural Commissioners', agencyUrl: 'https://www.cdpr.ca.gov/docs/license/liccert.htm', fee: '$60–$250', note: 'California runs the most complex programme in the country. DPR issues Qualified Applicator Certificates and Licences and Pest Control Adviser licences, while the 55 County Agricultural Commissioners issue Private Applicator Certificates, register businesses locally and issue restricted material permits. Continuing education is 20–40 hours per two-year cycle.', compactMember: false },
